// Reporte determinista de acciones observables; no extrae razonamiento interno.
const data = $input.first().json;
const source = $('Chat de prueba').first().json;
const steps = Array.isArray(data.intermediateSteps) ? data.intermediateSteps : [];
const error = data.error
  ? String(typeof data.error === 'string' ? data.error : (data.error.message || JSON.stringify(data.error)))
  : '';
const output = typeof data.output === 'string'
  ? data.output
  : (data.output ? JSON.stringify(data.output) : 'No se obtuvo una respuesta. Revisión humana necesaria.');
const toolEvents = steps.map((step, index) => ({
  paso: index + 1,
  herramienta: String(step.action?.tool || step.tool || 'No identificada'),
  resultado_observable: typeof step.observation === 'string'
    ? step.observation.slice(0, 5000)
    : JSON.stringify(step.observation ?? null).slice(0, 5000),
}));
const audit = {
  checkpoint: 'M1 - Agente base Electro Alem',
  execution_id: String($execution.id),
  session_id: String(source.sessionId || ''),
  fecha: $now.toISO(),
  estado_agente: error ? 'ERROR - REVISAR' : 'RESPUESTA_GENERADA - REVISAR',
  cantidad_llamadas_herramientas: toolEvents.length,
  herramientas: toolEvents,
  error: error.slice(0, 2000),
  respuesta: output,
};
// El contador corresponde a llamadas de herramientas, no a vueltas del modelo.
// El éxito del envío se comprueba por separado en el nodo Gmail y en la bandeja.
return [{ json: {
  output: error ? 'No pude completar la consulta. Se requiere revisión humana.' : output,
  audit,
  asunto: `[CP1 Electro Alem] ${audit.estado_agente} | ${audit.execution_id}`,
  reporte: JSON.stringify(audit, null, 2),
} }];
